@extends('admin.layouts.app') @section('title',$menu->exists?'Edit menu':'Create menu') @section('content')<h1 class="page-title mb-4">{{ $menu->exists?'Edit menu':'Create menu' }}</h1><form method="POST" action="{{ $menu->exists?route('admin.menus.update',$menu):route('admin.menus.store') }}">@csrf @if($menu->exists)@method('PUT')@endif<div class="content-card mb-4"><div class="row g-3"><div class="col-md-6"><label class="form-label">Menu name</label><input class="form-control" name="name" value="{{ old('name',$menu->name) }}" required></div><div class="col-md-6"><label class="form-label">Location key</label><input class="form-control" name="location" value="{{ old('location',$menu->location) }}" placeholder="primary" required></div></div></div><div class="content-card"><h2 class="section-title">Menu links</h2>@for($i=0;$i<5;$i++)@php($item=$menu->items->get($i))<div class="row g-2 mb-3"><div class="col-md-4"><label class="form-label">Label {{ $i+1 }}</label><input class="form-control" name="items[{{ $i }}][label]" value="{{ old('items.'.$i.'.label',$item?->label) }}"></div><div class="col-md-6"><label class="form-label">URL</label><input class="form-control" name="items[{{ $i }}][url]" value="{{ old('items.'.$i.'.url',$item?->url) }}"></div><div class="col-md-2"><label class="form-label">Target</label><select class="form-select" name="items[{{ $i }}][target]"><option value="_self">Same tab</option><option value="_blank" @selected($item?->target==='_blank')>New tab</option></select></div></div>@endfor<button class="btn btn-primary mt-3">Save menu</button></div></form>@endsection